import * as THREE from 'three';
import { CONFIG } from '../../config';
import { ATLAS_ROWS } from './hulls';

/* =====================================================================
   ATLAS BIỂN TÊN TÀU — vẽ bằng canvas (không ảnh ngoài). Mỗi tên một hàng; hàng cuối trắng (mọi bộ phận khác lấy uv ở đây).
   Hàng r chiếm v ∈ [r/ROWS, (r+1)/ROWS] (flipY mặc định ⇒ hàng 0 nằm ở đáy canvas).
   Tên hư cấu (CONFIG.boats.names), không dùng tên hãng thật.
   ===================================================================== */
const W = 512, H = 64;
export function btNameAtlas(): THREE.CanvasTexture {
  const c = document.createElement('canvas'); c.width = W; c.height = H * ATLAS_ROWS;
  const g = c.getContext('2d')!;
  const names = CONFIG.boats.names;
  for (let r = 0; r < ATLAS_ROWS; r++) {
    const y = c.height - (r + 1) * H;
    if (r === ATLAS_ROWS - 1) { g.fillStyle = '#ffffff'; g.fillRect(0, y, W, H); continue; }   // hàng trắng
    g.fillStyle = '#16233f'; g.fillRect(0, y, W, H);
    g.strokeStyle = '#e8c24a'; g.lineWidth = 4; g.strokeRect(4, y + 4, W - 8, H - 8);
    g.fillStyle = '#ffffff'; g.font = 'bold 40px sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(names[r], W / 2, y + H / 2 + 2, W - 30);
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
  return t;
}

import * as THREE from 'three';
import { CONFIG } from '../../config';
import { shared } from '../../core/shared';
import { ATLAS_ROWS } from './hulls';
import { btNameAtlas } from './atlas';

/* =====================================================================
   VẬT LIỆU ĐỘI TÀU — một vật liệu cho mọi tàu (D-026).
   - aPart (theo đỉnh) ≠ aBoat.x (theo instance) ⇒ thu đỉnh về gốc: tam giác suy biến, không rasterize ⇒ một InstancedMesh vẽ nhiều kiểu.
   - aBoat = (kiểu, biến thể màu sọc, màu LED, tên); aGlow (theo đỉnh) = loại đèn (hulls.ts → Glow).
   - Đèn đêm bằng emissive nhân uNight; không đèn thật.
   Bóng đổ dùng btDepthMaterial cùng bản vá, nếu không lượt vẽ bóng sẽ vẽ chồng mọi kiểu.
   ===================================================================== */
const B = CONFIG.boats;
const STRIPES = [0xc23b2a, 0x2f6fbf, 0xe0782a];   // màu sọc thân theo biến thể: đỏ, xanh dương, cam (ảnh tham chiếu)

const VS_HEAD = /* glsl */`
attribute float aPart;
attribute float aGlow;
attribute vec4 aBoat;
varying float vGlow;
varying vec4 vBoat;
`;
const VS_COLLAPSE = /* glsl */`#include <begin_vertex>
if ( abs( aPart - aBoat.x ) > 0.5 ) transformed = vec3( 0.0 );`;

const uniforms = {
  uNight: shared.uNight,
  uStripe: { value: STRIPES.map((c) => new THREE.Color(c)) },
  uWin: { value: new THREE.Color(B.windowColor).multiplyScalar(B.windowGain) }
};

export const btFleetMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.55, metalness: 0.05, map: btNameAtlas() });
btFleetMaterial.name = 'boatFleet';
btFleetMaterial.onBeforeCompile = (s) => {
  Object.assign(s.uniforms, uniforms);
  s.vertexShader = VS_HEAD + s.vertexShader
    .replace('#include <begin_vertex>', VS_COLLAPSE)
    .replace('#include <uv_vertex>', `#include <uv_vertex>
vGlow = aGlow; vBoat = aBoat;
if ( aGlow > 4.5 && aGlow < 5.5 ) vMapUv.y += aBoat.w / ${ATLAS_ROWS.toFixed(1)};   // biển tên: dịch tới hàng tên của tàu`);
  s.fragmentShader = /* glsl */`
uniform float uNight;
uniform vec3 uStripe[ ${STRIPES.length} ];
uniform vec3 uWin;
varying float vGlow;
varying vec4 vBoat;
` + s.fragmentShader
    .replace('#include <color_fragment>', `#include <color_fragment>
if ( vGlow > 6.5 ) diffuseColor.rgb = uStripe[ int( clamp( vBoat.y, 0.0, ${(STRIPES.length - 1).toFixed(1)} ) ) ];   // sọc thân theo biến thể`)
    .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
if ( vGlow > 0.5 && vGlow < 1.5 ) totalEmissiveRadiance += uWin * uNight;   // cửa sổ cabin vàng ấm`);
  btFleetMaterial.userData.vs = s.vertexShader;
};
btFleetMaterial.customProgramCacheKey = () => 'boatFleet';

export const btDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
btDepthMaterial.onBeforeCompile = (s) => {
  s.vertexShader = 'attribute float aPart;\nattribute vec4 aBoat;\n' + s.vertexShader.replace('#include <begin_vertex>', VS_COLLAPSE);
  btDepthMaterial.userData.vs = s.vertexShader;
};
btDepthMaterial.customProgramCacheKey = () => 'boatDepth';

import * as THREE from 'three';
import type { BoatTypeId } from '../../config';
import { btBuildFleetGeometry, BOAT_TYPES } from './hulls';
import { btFleetMaterial, btDepthMaterial } from './material';

/* =====================================================================
   ĐỘI TÀU (fleet) — một InstancedMesh cho mỗi nhóm tàu = 1 lệnh vẽ (thay 3 khối hộp thân / cabin / mái).
   Hình học gộp các kiểu nhóm cần; aBoat (instance) chọn kiểu, biến thể, màu LED, tên.
   ===================================================================== */
export interface BoatInfo { type: BoatTypeId; variant: number; led: number; name: number }
export interface BoatFleet { mesh: THREE.InstancedMesh; types: BoatTypeId[]; info: THREE.InstancedBufferAttribute }

export const btFleets: BoatFleet[] = [];   // để test (__app.boats.fleets)
const HIDDEN = new THREE.Matrix4().makeScale(0, 0, 0);

export function btCreateFleet(capacity: number, types: BoatTypeId[], parent: THREE.Object3D, name: string): BoatFleet {
  const geo = btBuildFleetGeometry(types), info = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
  geo.setAttribute('aBoat', info);
  const mesh = new THREE.InstancedMesh(geo, btFleetMaterial, capacity);
  mesh.name = name; mesh.customDepthMaterial = btDepthMaterial; mesh.frustumCulled = false; mesh.castShadow = true;
  for (let i = 0; i < capacity; i++) mesh.setMatrixAt(i, HIDDEN);
  parent.add(mesh);
  const f = { mesh, types, info }; btFleets.push(f);
  return f;
}
/* Gán kiểu / biến thể / LED / tên — chỉ gọi lúc dựng */
export function btSetInfo(f: BoatFleet, i: number, b: BoatInfo) {
  f.info.setXYZW(i, BOAT_TYPES.indexOf(b.type), b.variant, b.led, b.name); f.info.needsUpdate = true;
}
const _m = new THREE.Matrix4(), _s = new THREE.Vector3();
/* Đặt tàu i: base = điểm mặt nước dưới tâm tàu, q = hướng + tròng trành, len = chiều dài (m; hình học dài 1) */
export function btSetBoat(f: BoatFleet, i: number, base: THREE.Vector3, q: THREE.Quaternion, len: number) {
  f.mesh.setMatrixAt(i, _m.compose(base, q, _s.setScalar(len)));
}
export function btHideBoat(f: BoatFleet, i: number) { f.mesh.setMatrixAt(i, HIDDEN); }
export function btCommit(f: BoatFleet) { f.mesh.instanceMatrix.needsUpdate = true; }

